import{_ as l}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as i,D as g,o as n,c as h,I as c,w as d,k as o,a as u,R as p,b,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const C=JSON.parse('{"title":"Workflow、Multi-Agent、Evals 与 Tracing","description":"","frontmatter":{"title":"Workflow、Multi-Agent、Evals 与 Tracing","author":"阿源","date":"2026/10/07 00:00","categories":["Agent 开发"],"tags":["Workflow","Multi-Agent","Evals","Tracing","Browser","Sandbox"],"status":"预览版导航"},"headers":[],"relativePath":"courses/agent/01-项目与知识库导航/06-工作流多Agent评测与可观测性.md","filePath":"courses/agent/01-项目与知识库导航/06-工作流多Agent评测与可观测性.md","lastUpdated":1791349179000}'),m={name:"courses/agent/01-项目与知识库导航/06-工作流多Agent评测与可观测性.md"},_=o("h1",{id:"workflow、multi-agent、evals-与-tracing",tabindex:"-1"},[u("Workflow、Multi-Agent、Evals 与 Tracing "),o("a",{class:"header-anchor",href:"#workflow、multi-agent、evals-与-tracing","aria-label":'Permalink to "Workflow、Multi-Agent、Evals 与 Tracing"'},"​")],-1),k=p('<p>这一页把“怎么编排”“怎么观测”“怎么执行”放在同一张地图里。先用单 Agent 状态机表达流程，再决定是否需要多 Agent；先记录可审计 trace，再谈 LLM-as-Judge；先在无登录本地页面或临时 sandbox 中实验，再接入浏览器和代码执行。</p><h2 id="crewai" tabindex="-1">CrewAI <a class="header-anchor" href="#crewai" aria-label="Permalink to &quot;CrewAI&quot;">​</a></h2><p>官方入口：<a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">文档</a> · <a href="https://github.com/crewAIInc/crewAI" target="_blank" rel="noreferrer">GitHub</a></p><ul><li><strong>解决的问题</strong>：提供 role/task/crew/flow 等多 Agent 编排方式，便于比较协作抽象与显式状态机。</li><li><strong>推荐学习内容</strong>：先理解单 Agent 和确定性 Workflow，再阅读 delegation、state、guardrail 和 observability；不要默认多 Agent 更好。</li><li><strong>前置知识</strong>：第 02、05、09 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：Agents、Tasks、Flows、Guardrails、Observability。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Crew/Flow 的协作层与 dsh 插件协作对照，但 dsh 的核心可组合性来自 Cordis plugin context。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="autogen" tabindex="-1">AutoGen <a class="header-anchor" href="#autogen" aria-label="Permalink to &quot;AutoGen&quot;">​</a></h2><p>官方入口：<a href="https://microsoft.github.io/autogen/stable/" target="_blank" rel="noreferrer">稳定版文档</a> · <a href="https://github.com/microsoft/autogen" target="_blank" rel="noreferrer">GitHub</a></p><ul><li><strong>解决的问题</strong>：展示消息驱动的多 Agent 对话、团队、工具和可扩展运行时。</li><li><strong>推荐学习内容</strong>：阅读 agent protocol、team runtime、termination 和 intervention，比较消息图与状态图的故障边界。</li><li><strong>前置知识</strong>：Message、Role、State；第 03、09 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：AgentChat、Core、Teams、Termination。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Agent message/runtime 可与 dsh 事件系统和插件协作对照，不等同于 Cordis 生命周期。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="openai-evals" tabindex="-1">OpenAI Evals <a class="header-anchor" href="#openai-evals" aria-label="Permalink to &quot;OpenAI Evals&quot;">​</a></h2><p>官方入口：<a href="https://github.com/openai/evals" target="_blank" rel="noreferrer">GitHub</a></p><ul><li><strong>解决的问题</strong>：为模型和 Agent 建立数据集、评测模板、可复现运行和回归对比。</li><li><strong>推荐学习内容</strong>：先以确定性 parser/schema 测试起步，再把工具轨迹和最终答案分层纳入数据集。</li><li><strong>前置知识</strong>：第 04、10 章；测试断言与 JSONL 基础。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：evals registry、sample evals、model graded evals、CLI。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：评测输入、轨迹和结果对应 dsh 的 session/event 记录，适合验证 driver 与插件回归。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="langsmith-tracing" tabindex="-1">LangSmith Tracing <a class="header-anchor" href="#langsmith-tracing" aria-label="Permalink to &quot;LangSmith Tracing&quot;">​</a></h2><p>官方入口：<a href="https://docs.langchain.com/langsmith/observability" target="_blank" rel="noreferrer">Observability 文档</a> · <a href="https://docs.langchain.com/langsmith/observability-concepts" target="_blank" rel="noreferrer">Tracing 文档</a></p><ul><li><strong>解决的问题</strong>：记录运行、节点、工具和模型调用的 trace/span，定位 Agent 失败与成本。</li><li><strong>推荐学习内容</strong>：先掌握 trace/span/event 的数据模型，再比较采样、敏感字段脱敏和离线评测关联。</li><li><strong>前置知识</strong>：第 09、10 章；事件日志和指标基础。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Observability、Tracing、Datasets、Online evaluations。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：trace/span 可映射到 dsh event bus 和 driver 轨迹，但需自行审计敏感工具参数。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="arize-phoenix" tabindex="-1">Arize Phoenix <a class="header-anchor" href="#arize-phoenix" aria-label="Permalink to &quot;Arize Phoenix&quot;">​</a></h2><p>官方入口：<a href="https://github.com/Arize-ai/phoenix" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://arize.com/docs/phoenix" target="_blank" rel="noreferrer">文档</a></p><ul><li><strong>解决的问题</strong>：提供开放式 LLM/Agent tracing、评测和本地观测界面。</li><li><strong>推荐学习内容</strong>：用本地示例观察 span 属性、检索/生成评测和敏感数据配置，不把展示结果当作正确性证明。</li><li><strong>前置知识</strong>：Trace、Span、RAG eval；第 08、10 章。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：OpenTelemetry tracing、evaluators、RAG analysis、self-hosting。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：OpenTelemetry span 可承载 dsh driver、plugin 和 tool event 的跨层观测。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="browser-use" tabindex="-1">Browser Use <a class="header-anchor" href="#browser-use" aria-label="Permalink to &quot;Browser Use&quot;">​</a></h2><p>官方入口：<a href="https://github.com/browser-use/browser-use" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://docs.browser-use.com/" target="_blank" rel="noreferrer">文档</a></p><ul><li><strong>解决的问题</strong>：展示让 Agent 观察和操作真实浏览器的状态、动作、工具与执行环境。</li><li><strong>推荐学习内容</strong>：先用无登录、无写入的本地页面实验，阅读浏览器 session、动作确认、超时和权限；真实账号必须隔离。</li><li><strong>前置知识</strong>：Tool Calling、State、Guardrail；第 04、10 章。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：quickstart、browser session、agent actions、security and deployment。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：浏览器动作可视作 dsh tool plugin；权限、审批、session 隔离和审计不能交给模型默认决定。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="playwright" tabindex="-1">Playwright <a class="header-anchor" href="#playwright" aria-label="Permalink to &quot;Playwright&quot;">​</a></h2><p>官方入口：<a href="https://playwright.dev/docs/intro" target="_blank" rel="noreferrer">入门文档</a> · <a href="https://playwright.dev/docs/browsers" target="_blank" rel="noreferrer">浏览器文档</a></p><ul><li><strong>解决的问题</strong>：提供可重复的浏览器控制和测试基础，让 Agent 浏览器工具有确定性执行层。</li><li><strong>推荐学习内容</strong>：先掌握 locator、context、timeouts、tracing 和无头运行，再阅读 Agent 如何生成受控动作。</li><li><strong>前置知识</strong>：Python 函数、异常和测试；浏览器基础。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Library、Browser contexts、Auto-waiting、Trace viewer。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Playwright context 是 dsh 浏览器插件可拥有的隔离资源；Harness 仍负责授权与审批。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="e2b-code-interpreter" tabindex="-1">E2B Code Interpreter <a class="header-anchor" href="#e2b-code-interpreter" aria-label="Permalink to &quot;E2B Code Interpreter&quot;">​</a></h2><p>官方入口：<a href="https://github.com/e2b-dev/E2B" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://e2b.dev/docs" target="_blank" rel="noreferrer">文档</a></p><ul><li><strong>解决的问题</strong>：提供临时隔离执行环境，帮助理解 Agent 生成代码与宿主文件系统的安全边界。</li><li><strong>推荐学习内容</strong>：重点读 sandbox 生命周期、网络/文件权限、超时和清理；危险代码只在受控测试数据中运行。</li><li><strong>前置知识</strong>：Tool、Sandbox、最小权限；第 04、10 章。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：sandbox lifecycle、filesystem、network controls、timeouts and cleanup。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Sandbox 是 dsh 执行插件的隔离实现，不能由 <code>LocalPythonExecutor</code> 等 best-effort 模式替代。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="统一的观测字段" tabindex="-1">统一的观测字段 <a class="header-anchor" href="#统一的观测字段" aria-label="Permalink to &quot;统一的观测字段&quot;">​</a></h2><p>无论选择哪个框架或服务，至少为每次 run 保存输入摘要、模型/配置版本、session id、每个 tool call 的参数和结果、状态转移、重试、人工介入、停止原因、token/延迟/成本以及最终产物验证结果。文件、Shell、浏览器、网络和外发动作要单独记录权限和审批。</p>',27);function w(e,A,v,x,y,T){const a=l,s=g("ClientOnly");return n(),h("div",null,[_,c(s,null,{default:d(()=>{var r,t;return[(((r=e.$frontmatter)==null?void 0:r.aside)??!0)&&(((t=e.$frontmatter)==null?void 0:t.showArticleMetadata)??!0)?(n(),b(a,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),k])}const H=i(m,[["render",w]]);export{C as __pageData,H as default};
